const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const crater = ee.Geometry.Point([-155.2834, 19.4068]);
  const roi = crater.buffer(10000); // 10 km radius

  // July 20, 2025, 10:44 am HST = 20:44 UTC
  const targetTime = ee.Date('2025-07-20T20:44:00');
  const startTime = targetTime.advance(-30, 'minute');
  const endTime = targetTime.advance(30, 'minute');

  console.log('Target time: 2025-07-20 10:44 HST (20:44 UTC)');
  console.log('Region: 10km radius around Halemaʻumaʻu Crater');

  // 2. Data Acquisition - GOES-18 for Hawaii
  let goes = ee.ImageCollection('NOAA/GOES/18/MCMIPF')
    .filterBounds(roi)
    .filterDate(startTime, endTime);

  const goesCount = goes.size().getInfo();
  console.log(`GOES-18 images found: ${goesCount}`);

  if (goesCount === 0) {
    console.log('No GOES-18 imagery available for this time.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get closest image to target time
  const img = ee.Image(goes.sort('system:time_start').first());
  const imgTime = new Date(img.get('system:time_start').getInfo());
  console.log(`Using image from: ${imgTime.toISOString()}`);

  // 3. Extract cloud mask and calculate cloud area
  // GOES has DQF (Data Quality Flag) where clouds are identified
  const cloudMask = img.select('DQF').eq(0); // DQF=0 indicates good quality (clear)
  const clouds = cloudMask.not(); // Invert to get clouds

  // Count cloud pixels
  const cloudStats = clouds.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 2000,
    maxPixels: 1e9
  });

  const cloudPixels = cloudStats.get('DQF').getInfo();

  if (cloudPixels === null) {
    console.log('Cloud calculation failed.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 4. Estimate volcanic plume area using thermal and SO2 indicators
  // Use brightness temperature difference for plume detection
  const bt11 = img.select('CMI_C13'); // 10.3 μm IR band
  const bt14 = img.select('CMI_C15'); // 12.3 μm IR band

  // Volcanic plume shows brightness temperature anomaly
  const btDiff = bt14.subtract(bt11);

  // Plume detection: negative BT difference and high thermal signature
  const plume = btDiff.lt(-2).and(bt11.gt(270)); // Typical volcanic plume signature

  const plumeStats = plume.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 2000,
    maxPixels: 1e9
  });

  const plumePixels = plumeStats.get('CMI_C15').getInfo();

  if (plumePixels === null) {
    console.log('Plume calculation failed.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 5. Check for valid pixels
  const totalStats = img.select('CMI_C13').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 2000,
    maxPixels: 1e9
  });

  const totalPixels = totalStats.get('CMI_C13').getInfo();

  if (totalPixels === 0) {
    console.log('No valid pixels in region.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 6. Compare areas
  console.log(`Total pixels: ${totalPixels}`);
  console.log(`Cloud pixels: ${cloudPixels}`);
  console.log(`Plume pixels: ${plumePixels}`);
  console.log(`Cloud coverage: ${((cloudPixels/totalPixels)*100).toFixed(1)}%`);
  console.log(`Plume coverage: ${((plumePixels/totalPixels)*100).toFixed(1)}%`);

  if (cloudPixels > plumePixels) {
    console.log('Clouds cover larger area than volcanic plume.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Volcanic plume covers equal or larger area than clouds.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
